def run(frames, params):
    import numpy as np
    import math
    import json

    def obj(x):
        return x if isinstance(x, dict) else {}

    def arr(x):
        meta = obj(x)
        if isinstance(x, dict):
            x = x.get('values', x.get('data'))
        if x is None:
            return None
        try:
            a = np.asarray(x, dtype=float)
            if not a.size:
                return None
            if 'shape' in meta and tuple(meta['shape']) != a.shape:
                return None
            return a
        except (TypeError, ValueError, OverflowError):
            return None

    def number(x):
        try:
            v = float(x)
            return v if math.isfinite(v) else None
        except (TypeError, ValueError, OverflowError):
            return None

    def param(k, default, upper):
        v = number(obj(params).get(k, default))
        return v if v is not None and 0 < v <= upper else default

    mt = param('marker_change_px', 2.0, 10000)
    rt = param('rgb_change', 0.02, 1)
    rois = obj(obj(params).get('camera_rois'))
    fs = [obj(f) for f in list(frames)[-4:]] if frames is not None else []
    sides = ('left', 'right')

    def quant(a, q=(0.5, 0.9)):
        return np.quantile(a, q).tolist() if a.size else None

    def quat(q):
        q = arr(q)
        if q is None or q.shape != (4,) or not np.isfinite(q).all():
            return None
        scale = np.max(np.abs(q))
        if scale < 1e-12:
            return None
        q = q / scale
        return q / np.linalg.norm(q)

    def rotation(q):
        q = quat(q)
        if q is None:
            return None
        w, x, y, z = q
        return np.array([[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w)],
                         [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w)],
                         [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y)]])

    def pose(f):
        s = obj(f.get('state'))
        p = arr(s.get('eef_pose_wxyz'))
        if s.get('pose_frame', 'world') != 'world' or s.get('position_units', 'm') != 'm':
            return None
        if p is None or p.shape != (7,) or not np.isfinite(p).all():
            return None
        q = quat(p[3:])
        return (p[:3], q, s.get('eef_frame')) if q is not None else None

    def hand_delta(a, b):
        if a is None or b is None or a[2] != b[2]:
            return None
        d = b[0] - a[0]
        angle = float(np.degrees(2*np.arccos(np.clip(abs(a[1] @ b[1]), 0, 1))))
        return {'world_xyz_m': d.tolist(), 'rotation_deg': angle,
                'nearly_fixed': bool(np.linalg.norm(d) < 0.0001 and angle < 0.05)}

    def depth(x):
        a = arr(x)
        if a is not None and a.ndim == 3 and a.shape[2] == 1:
            a = a[:, :, 0]
        return a if a is not None and a.ndim == 2 else None

    def depth_stats(a):
        if a is None:
            return None
        good = np.isfinite(a) & (a > 0)
        return {'valid_fraction': float(good.mean()),
                'p10_p50_p90': quant(a[good], (0.1, 0.5, 0.9))}

    def image_scale(x, a, owner):
        meta = obj(x)
        v = number(meta.get('rgb_scale', owner.get('rgb_scale')))
        if v in (1, 255):
            return v, 'declared'
        raw = meta.get('values', meta.get('data')) if isinstance(x, dict) else x
        try:
            dtype = str(meta.get('dtype', np.asarray(raw).dtype))
        except (TypeError, ValueError):
            dtype = ''
        if dtype == 'uint8':
            return 255.0, 'dtype'
        good = a[np.isfinite(a)]
        if not good.size or good.min() < 0 or good.max() > 255:
            return None, 'unknown'
        return (1.0 if good.max() <= 1 else 255.0), 'inferred_range'

    def rgb_pair(x, y, ox, oy):
        a, b = arr(x), arr(y)
        if a is None or b is None or a.shape != b.shape or a.ndim != 3 or a.shape[2] != 3:
            return None
        for owner, data in ((ox, a), (oy, b)):
            size = arr(owner.get('image_size'))
            if size is not None and (size.shape != (2,) or not np.array_equal(size, data.shape[:2])):
                return None
        sa, ka = image_scale(x, a, ox)
        sb, kb = image_scale(y, b, oy)
        if sa is None or sb is None:
            return None
        if ka == kb == 'inferred_range':
            sa = sb = max(sa, sb)
        good = np.isfinite(a).all(axis=2) & np.isfinite(b).all(axis=2)
        if not good.any():
            return None
        av, bv = a[good], b[good]
        if av.min() < 0 or bv.min() < 0 or av.max() > sa or bv.max() > sb:
            return None
        d = np.abs(av/sa - bv/sb).mean(axis=1)
        return {'mean_abs': float(d.mean()), 'changed_fraction': float((d > rt).mean()),
                'valid_fraction': float(good.mean()),
                'scale': [sa, sb], 'scale_inferred': ka == 'inferred_range' or kb == 'inferred_range'}

    def tactile(f, s):
        return obj(obj(f.get('tactile')).get(s))

    def tactile_depth(t):
        if t.get('depth_units') != 'mm':
            return None
        semantics = t.get('depth_semantics')
        if semantics is not None and semantics != 'native_sensor_camera_depth_not_indentation':
            return None
        d = depth(t.get('depth'))
        size = arr(t.get('depth_image_size'))
        if d is not None and size is not None and (size.shape != (2,) or not np.array_equal(size, d.shape)):
            return None
        return d

    def depth_change(a, b):
        if a is None or b is None or a.shape != b.shape:
            return None
        good = np.isfinite(a) & np.isfinite(b) & (a > 0) & (b > 0)
        if not good.any():
            return None
        return {'p90_mm': float(np.quantile(np.abs(b[good]-a[good]), 0.9)),
                'valid_fraction': float(good.mean())}

    def markers(t):
        expected = {'marker_units': 'pixels', 'marker_coordinate_order': 'x,y',
                    'marker_origin': 'top_left', 'marker_axes': 'x_right_y_down'}
        if any(t.get(k) != v for k, v in expected.items()):
            return None, {'status': 'unknown_metadata'}
        r, d, c = [arr(t.get(k)) for k in ('marker_reference', 'marker_displacement', 'marker_current')]
        if r is None or r.ndim != 2 or r.shape[1] != 2:
            return None, {'status': 'unknown_reference'}
        if d is None and c is not None and c.shape == r.shape:
            d = c-r
        if d is None or d.shape != r.shape:
            return None, {'status': 'unknown_displacement'}
        good = np.isfinite(r).all(axis=1) & np.isfinite(d).all(axis=1)
        if c is not None:
            if c.shape != r.shape:
                return None, {'status': 'incompatible_current'}
            good &= np.isfinite(c).all(axis=1)
            if good.any() and np.max(np.linalg.norm(c[good]-r[good]-d[good], axis=1)) > 0.1:
                return None, {'status': 'inconsistent_within_frame_rows'}
        r, d = r[good], d[good]
        if not len(r):
            return None, {'status': 'no_finite_markers'}
        keys, inv = np.unique(np.round(r, 3), axis=0, return_inverse=True)
        vals = np.array([np.median(d[inv == k], axis=0) for k in range(len(keys))])
        n = len(keys)
        if n > 512:
            ix = np.linspace(0, n-1, 512).astype(int)
            keys, vals = keys[ix], vals[ix]
        edge = None
        size = arr(t.get('image_size'))
        if size is not None and size.shape == (2,) and np.isfinite(size).all() and np.min(size) > 0:
            h, w = size
            cur = keys + vals
            edge = float(((cur[:, 0] < 0.02*w) | (cur[:, 0] >= 0.98*w) |
                          (cur[:, 1] < 0.02*h) | (cur[:, 1] >= 0.98*h)).mean())
        return (keys, vals), {'status': 'measured', 'unique_n': n, 'used_n': len(keys),
            'duplicates': len(r)-n, 'median_xy_px': np.median(vals, axis=0).tolist(),
            'mag_p50_p90_px': quant(np.linalg.norm(vals, axis=1)), 'edge_fraction': edge,
            'tracking_quality': number(t.get('tracking_quality'))}

    def marker_delta(a, b, ta, tb):
        if a is None or b is None:
            return None
        sa, sb = arr(ta.get('image_size')), arr(tb.get('image_size'))
        if sa is None or sb is None or sa.shape != (2,) or sb.shape != (2,) or not np.array_equal(sa, sb):
            return {'status': 'unknown_image_compatibility'}
        if not ta.get('reference_kind') or ta.get('reference_kind') != tb.get('reference_kind'):
            return {'status': 'unknown_reference_continuity'}
        for key in ('reference_id', 'marker_reference_id'):
            if (key in ta or key in tb) and ta.get(key) != tb.get(key):
                return {'status': 'reference_changed'}
        ra, da = a
        rb, db = b
        if min(len(ra), len(rb)) < 6:
            return {'status': 'insufficient_markers'}
        def spacing(r):
            d = np.linalg.norm(r[:, None, :] - r[None, :, :], axis=2)
            np.fill_diagonal(d, np.inf)
            return float(np.median(d.min(axis=1)))
        sp = min(spacing(ra), spacing(rb))
        gate = max(0.5, 0.2*sp)
        dist = np.linalg.norm(ra[:, None, :] - rb[None, :, :], axis=2)
        j = dist.argmin(axis=1)
        back = dist.argmin(axis=0)
        i = np.arange(len(ra))
        keep = (back[j] == i) & (dist[i, j] <= gate)
        i, j = i[keep], j[keep]
        coverage = len(i)/max(len(ra), len(rb))
        out = {'status': 'insufficient_overlap', 'n': len(i), 'coverage': coverage}
        if len(i) < 6 or coverage < 0.5:
            return out
        dv = db[j]-da[i]
        med = np.median(dv, axis=0)
        mag = np.linalg.norm(dv, axis=1)
        out.update({'status': 'matched', 'xy_px': med.tolist(),
            'p50_p90_px': quant(mag), 'match_p90_px': float(np.quantile(dist[i, j], 0.9)),
            'residual_p90_px': float(np.quantile(np.linalg.norm(dv-med, axis=1), 0.9)),
            'large_vs_spacing': bool(np.median(mag) > 0.5*sp)})
        return out

    def fit_plane(p):
        if len(p) < 24 or not np.isfinite(p).all():
            return None
        use = np.ones(len(p), dtype=bool)
        try:
            for _ in range(4):
                center = p[use].mean(axis=0)
                _, sv, vt = np.linalg.svd(p[use]-center, full_matrices=False)
                normal = vt[-1]
                residual = np.abs((p-center) @ normal)
                use = residual <= max(0.003, float(np.quantile(residual, 0.7)))
                if use.sum() < 24:
                    return None
            center = p[use].mean(axis=0)
            _, sv, vt = np.linalg.svd(p[use]-center, full_matrices=False)
            normal = vt[-1]
            residual = np.abs((p-center) @ normal)
            good = residual <= 0.003
            if good.mean() < 0.6 or good.sum() < 24 or sv[1]/math.sqrt(use.sum()) < 0.0005:
                return None
            if normal @ center > 0:
                normal = -normal
            return normal, float(good.mean()), float(np.quantile(residual[good], 0.9))
        except np.linalg.LinAlgError:
            return None

    def camera(f, name, hand):
        c = obj(obj(f.get('cameras')).get(name))
        cal = obj(c.get('calibration'))
        d = depth(c.get('depth'))
        unit = cal.get('depth_units', c.get('depth_units'))
        if d is None or unit not in ('m', 'mm'):
            return {'status': 'unknown_dense_depth_or_units'}
        if unit == 'mm':
            d = d*0.001
        h, w = d.shape
        roi = arr(rois.get(name, [0, 0, 1, 1]))
        if roi is None or roi.shape != (4,) or not np.isfinite(roi).all() or np.any(roi < 0) or np.any(roi > 1):
            return {'status': 'invalid_roi'}
        if roi[2] <= roi[0] or roi[3] <= roi[1]:
            return {'status': 'empty_roi'}
        r0, c0 = int(roi[0]*h), int(roi[1]*w)
        r1, c1 = int(np.ceil(roi[2]*h)), int(np.ceil(roi[3]*w))
        patch = d[r0:r1, c0:c1]
        out = {'status': 'depth_only', 'roi_rc': [r0, c0, r1, c1],
               'depth_m': depth_stats(patch), 'surface': None}
        k = arr(cal.get('intrinsics'))
        rot = rotation(cal.get('quaternion_wxyz'))
        if cal.get('camera_convention') != 'ros_optical' or k is None or k.shape != (3, 3):
            return out
        if cal.get('height') != h or cal.get('width') != w:
            out['status'] = 'calibration_size_mismatch'
            return out
        if not np.isfinite(k).all():
            return out
        try:
            ki = np.linalg.inv(k)
        except np.linalg.LinAlgError:
            return out
        stride = max(1, int(np.ceil(np.sqrt(patch.size/1024.0))))
        yy, xx = np.meshgrid(np.arange(r0, r1, stride), np.arange(c0, c1, stride), indexing='ij')
        z = d[yy, xx]
        good = np.isfinite(z) & (z > 0)
        yy, xx, z = yy[good], xx[good], z[good]
        rays = np.column_stack((xx, yy, np.ones(len(z)))) @ ki.T
        if not len(z) or np.any(np.abs(rays[:, 2]) < 1e-12):
            return out
        p = rays*(z/rays[:, 2])[:, None]
        fit = fit_plane(p)
        out['status'] = 'no_dominant_visible_plane'
        if fit is not None:
            n, support, residual = fit
            nw = rot @ n if rot is not None else None
            out['surface'] = {'normal_optical': n.tolist(),
                'normal_world': nw.tolist() if nw is not None else None,
                'support': support, 'residual_p90_m': residual, 'sample_n': len(p),
                'hand_z_angle_deg': float(np.degrees(np.arccos(np.clip(abs(nw @ rotation(hand[1])[:, 2]), 0, 1)))) if nw is not None and hand is not None else None}
            out['status'] = 'visible_patch_only'
        if name in rois:
            normals = []
            for row in range(2):
                for col in range(2):
                    mask = ((yy >= (r0+r1)/2) == bool(row)) & ((xx >= (c0+c1)/2) == bool(col))
                    fit = fit_plane(p[mask])
                    normals.append(fit[0] if fit is not None else None)
            ns = [n for n in normals if n is not None]
            spread = None
            if len(ns) >= 2:
                spread = max(float(np.degrees(np.arccos(np.clip(abs(a @ b), 0, 1)))) for a in ns for b in ns)
            out['tiles'] = {'normal_frame': 'world' if rot is not None else 'optical',
                'normals': [(rot @ n if rot is not None else n).tolist() if n is not None else None for n in normals],
                'max_unoriented_difference_deg': spread,
                'assessment': 'heterogeneous' if spread is not None and spread > 10 else ('locally_consistent' if len(ns) >= 3 else 'unknown')}
        return out

    def clock_interval(a, b):
        evidence = []
        dt = None
        for key in ('simulation_time_s', 'physics_step'):
            x, y = number(a.get(key)), number(b.get(key))
            if x is not None and y is not None:
                delta = y-x
                evidence.append(1 if delta > 0 else (-1 if delta < 0 else 0))
                if key == 'simulation_time_s':
                    dt = delta
        if -1 in evidence:
            return 'nonmonotonic', dt
        if 0 in evidence and 1 in evidence:
            return 'inconsistent_clock', dt
        if evidence and all(v == 0 for v in evidence):
            return 'no_time_advance', dt
        return ('advanced' if evidence else 'unknown_clock'), dt

    def flag_marker(m):
        return bool(m['p50_p90_px'][0] > mt) if m is not None and m.get('status') == 'matched' else None

    def flag_rgb(r):
        return bool(r['changed_fraction'] > 0.01) if r is not None and r['valid_fraction'] >= 0.5 else None

    def evidence(m, r):
        if m is None or r is None:
            return 'incomplete'
        if m and r:
            return 'marker_and_rgb'
        if m:
            return 'marker_only'
        if r:
            return 'rgb_only'
        return 'below_thresholds'

    out = {'frames': [{'index': i, 'step': number(f.get('step'))} for i, f in enumerate(fs)],
           'latest': None, 'intervals': [], 'window': {'peak': None, 'latest_evidence': None, 'decay_at_nearly_fixed_hand': None},
           'applicability': {'absolute_contact': 'unknown', 'reference_continuity': 'assumed_same_episode',
                'uncertainty': 'Coverage and spread are descriptive; tracking accuracy and physical cause are unknown.',
                'limits': 'Loaded references; pixels are not force; native tactile depth is not indentation; visible normals do not establish concealed geometry.'},
           'omitted': []}
    if not fs:
        return out
    poses = [pose(f) for f in fs]
    fields = [{s: markers(tactile(f, s)) for s in sides} for f in fs]
    depths = [{s: tactile_depth(tactile(f, s)) for s in sides} for f in fs]
    last = fs[-1]
    latest = {'frame': len(fs)-1, 'hand_z_world': rotation(poses[-1][1])[:, 2].tolist() if poses[-1] is not None else None,
              'tactile': {}, 'cameras': {}}
    for s in sides:
        t = tactile(last, s)
        kind = t.get('reference_kind')
        latest['tactile'][s] = {'markers': fields[-1][s][1],
            'reference_kind': str(kind)[:48] if kind is not None else None,
            'rgb_reference': rgb_pair(t.get('reference_rgb'), t.get('rgb'), t, t),
            'native_depth_mm': depth_stats(depths[-1][s])}
    latest['cameras'] = {n: camera(last, n, poses[-1]) for n in ('head', 'wrist')}
    out['latest'] = latest
    peak = -1.0
    for i in range(1, len(fs)):
        a, b = fs[i-1], fs[i]
        status, dt = clock_interval(a, b)
        rec = {'frames': [i-1, i], 'time': status, 'dt_s': dt,
               'hand': hand_delta(poses[i-1], poses[i]), 'tactile': {}, 'evidence': None}
        if status in ('no_time_advance', 'nonmonotonic', 'inconsistent_clock'):
            rec['evidence'] = 'no_independent_temporal_evidence'
            out['intervals'].append(rec)
            continue
        mf, rf, strengths = [], [], []
        for s in sides:
            ta, tb = tactile(a, s), tactile(b, s)
            m = marker_delta(fields[i-1][s][0], fields[i][s][0], ta, tb)
            r = rgb_pair(ta.get('rgb'), tb.get('rgb'), ta, tb)
            rec['tactile'][s] = {'markers': m, 'rgb': r,
                'native_depth': depth_change(depths[i-1][s], depths[i][s])}
            mf.append(flag_marker(m))
            rf.append(flag_rgb(r))
            strengths.append(m['p50_p90_px'][0] if m is not None and m.get('status') == 'matched' else None)
        rec['evidence'] = [evidence(m, r) for m, r in zip(mf, rf)]
        rec['opposite_image_x'] = None
        if all(v is not None for v in strengths):
            l = rec['tactile']['left']['markers']['xy_px'][0]
            r = rec['tactile']['right']['markers']['xy_px'][0]
            rec['opposite_image_x'] = bool(l*r < 0 and min(abs(l), abs(r)) > mt)
            strength = sum(strengths)/2
            if status == 'advanced' and strength > peak:
                peak = strength
                out['window']['peak'] = {'frames': [i-1, i], 'mean_marker_p50_px': strength,
                    'evidence': rec['evidence'], 'opposite_image_x': rec['opposite_image_x']}
        out['intervals'].append(rec)
    if out['intervals']:
        rec = out['intervals'][-1]
        out['window']['latest_evidence'] = {'frames': rec['frames'], 'time': rec['time'], 'evidence': rec['evidence']}
    if len(out['intervals']) >= 2:
        a, b = out['intervals'][-2:]
        eligible = all(r['time'] == 'advanced' and r['hand'] is not None and r['hand']['nearly_fixed'] and r['dt_s'] is not None and r['dt_s'] > 0 for r in (a, b))
        if eligible and max(a['dt_s'], b['dt_s'])/min(a['dt_s'], b['dt_s']) <= 1.2:
            vals = []
            for s in sides:
                ma, mb = a['tactile'][s]['markers'], b['tactile'][s]['markers']
                if ma is None or mb is None or ma.get('status') != 'matched' or mb.get('status') != 'matched' or min(ma['coverage'], mb['coverage']) < 0.8:
                    vals.append(None)
                else:
                    x, y = ma['p50_p90_px'][0], mb['p50_p90_px'][0]
                    vals.append({'p50_px': [x, y], 'decreased_by_half': bool(x > 0 and y <= 0.5*x),
                                 'latest_below_threshold': bool(y <= mt)})
            out['window']['decay_at_nearly_fixed_hand'] = {'frames': [a['frames'][0], a['frames'][1], b['frames'][1]],
                'left': vals[0], 'right': vals[1], 'interpretation': 'Observed change trend only; stability and cause unknown.'}

    def clean(x):
        if isinstance(x, dict):
            return {str(k): clean(v) for k, v in x.items()}
        if isinstance(x, np.ndarray):
            return clean(x.tolist())
        if isinstance(x, (list, tuple)):
            return [clean(v) for v in x]
        if isinstance(x, (bool, np.bool_)):
            return bool(x)
        if isinstance(x, (int, np.integer)):
            return int(x)
        if isinstance(x, (float, np.floating)):
            return round(float(x), 6) if math.isfinite(float(x)) else None
        return x

    out = clean(out)
    def too_big():
        return len(json.dumps(out, allow_nan=False)) >= 5900
    if too_big():
        for rec in out['intervals']:
            for t in rec['tactile'].values():
                r = t.get('rgb')
                if r is not None:
                    r.pop('scale', None)
                    r.pop('scale_inferred', None)
        out['omitted'].append('interval_rgb_scale_details')
    if too_big():
        for t in out['latest']['tactile'].values():
            t.pop('rgb_reference', None)
            t.pop('native_depth_mm', None)
        out['omitted'].append('latest_reference_rgb_and_depth_statistics')
    if too_big():
        for c in out['latest']['cameras'].values():
            tiles = c.get('tiles')
            if tiles is not None:
                tiles.pop('normals', None)
        out['omitted'].append('individual_tile_normals')
    if too_big():
        for rec in out['intervals']:
            for t in rec['tactile'].values():
                m = t.get('markers')
                if m is not None:
                    m.pop('match_p90_px', None)
                    m.pop('residual_p90_px', None)
        out['omitted'].append('interval_marker_residual_details')
    if too_big():
        out['latest']['cameras'] = {'status': 'omitted_for_budget'}
        out['omitted'].append('camera_details')
    if too_big():
        out['latest']['tactile'] = {'status': 'omitted_for_budget'}
        out['omitted'].append('latest_tactile_details')
    while too_big() and out['intervals']:
        rec = out['intervals'].pop(0)
        out['omitted'].append({'interval': rec['frames']})
    return out
